/** Actual atlas/CULL block consumer; isolated title fixture, not a world or activation claim. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class NativePropulsionRenderChecks {
 private record Scene(NativePropulsionEntity.Visual[] visual,ModelData[] data,int size,Direction facing){}
 private static NativePropulsionModel.Bake bake;private static Scene[] scenes,negative;private static BakedModel model;private static int frames,generation;private static boolean capture,done;private static int[][] baseline;private static long builds;
 private static final Direction[] FACINGS={Direction.NORTH,Direction.NORTH,Direction.SOUTH,Direction.EAST,Direction.WEST,Direction.UP,Direction.UP,Direction.DOWN,Direction.NORTH,Direction.NORTH,Direction.EAST,Direction.NORTH};
 private static boolean enabled(){return "true".equals(System.getenv("VANDOR_PROPULSION_RENDER_CHECK"));}private static void need(boolean yes,String text){if(!yes)throw new AssertionError("Propulsion GPU: "+text);}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)public static final class Models{@SubscribeEvent(priority=EventPriority.LOWEST)public static void bake(ModelEvent.ModifyBakingResult event){if(enabled())NativePropulsionModel.prepare(event.getModelBakery(),event.getModels(),event.getTextureGetter(),null,Minecraft.getInstance().getResourceManager());}}
 private static Scene scene(String id,Direction facing,boolean powered,boolean selected,int material,int brightness,int size,boolean joined){var visuals=new NativePropulsionEntity.Visual[size*size];var data=new ModelData[visuals.length];for(int x=0;x<size;x++)for(int y=0;y<size;y++){int i=x*size+y;visuals[i]=new NativePropulsionEntity.Visual(PropulsionDefinition.of(id),facing,powered,brightness,material,selected?3:0,selected,true,joined?new NativePropulsionEntity.Part(size,x,y):NativePropulsionEntity.Part.SINGLE,false);data[i]=ModelData.builder().with(NativePropulsionEntity.VISUAL,visuals[i]).build();}return new Scene(visuals,data,size,facing);}
 private static void prepare(){bake=NativePropulsionModel.currentBake();need(bake!=null,"prepared production chunk-model backend");String[] ids={"rocket_thruster","rocket_thruster","rocket_thruster","ion_drive","plasma_vent","impulse_engine","antigravity_plate","repulsor_array","vertical_hover_thruster","rocket_thruster_hexagonal","ion_drive_wedge_top_left","rocket_thruster_hexagonal"};scenes=new Scene[12];negative=new Scene[12];for(int i=0;i<12;i++){int material=i==2||i==4?64:9,brightness=i==2||i==4?7:15,size=i==11?3:1;scenes[i]=scene(ids[i],FACINGS[i],i!=1,i==2||i==4||i==5||i==8||i==9,material,brightness,size,true);negative[i]=scenes[i];}negative[1]=scene(ids[1],FACINGS[1],true,false,9,15,1,true);negative[3]=scene(ids[3],Direction.NORTH,true,false,9,15,1,true);negative[4]=scene(ids[4],FACINGS[4],true,true,9,7,1,true);negative[11]=scene(ids[11],FACINGS[11],true,false,9,15,3,false);model=NativePropulsionModel.wrap(bake.source(scenes[0].visual[0]),bake);}
 private static void align(PoseStack pose,Direction facing){switch(facing){case NORTH->pose.mulPose(Axis.YP.rotationDegrees(180));case EAST->pose.mulPose(Axis.YP.rotationDegrees(-90));case WEST->pose.mulPose(Axis.YP.rotationDegrees(90));case UP->pose.mulPose(Axis.XP.rotationDegrees(90));case DOWN->pose.mulPose(Axis.XP.rotationDegrees(-90));default->{}}}
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(done||!enabled()||!(event.getScreen() instanceof net.minecraft.client.gui.screens.TitleScreen))return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;if(bake==null)prepare();var gui=event.getGuiGraphics();gui.flush();com.mojang.blaze3d.systems.RenderSystem.clear(org.lwjgl.opengl.GL11.GL_DEPTH_BUFFER_BIT,Minecraft.ON_OSX);gui.fill(0,0,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),0xff202830);gui.flush();var buffers=mc.renderBuffers().bufferSource();var layer=NativePanelPlaybackRenderer.frameRenderType(true);for(int i=0;i<12;i++){var scene=frames<5?negative[i]:scenes[i];int px=10+(i%4)*155,py=8+(i/4)*112;gui.enableScissor(px,py,px+150,py+106);var pose=gui.pose();pose.pushPose();try{pose.translate(px+75,py+53,350);pose.scale(70F/scene.size,-70F/scene.size,70F/scene.size);pose.mulPose(Axis.XP.rotationDegrees(12));pose.mulPose(Axis.YP.rotationDegrees(-24));align(pose,FACINGS[i]);int right=com.vandorlabs.propulsion.PropulsionEmission.right(scene.facing.get3DDataValue()),up=com.vandorlabs.propulsion.PropulsionEmission.up(scene.facing.get3DDataValue());double half=(scene.size-1)*.5;pose.translate(-.5-com.vandorlabs.propulsion.PropulsionEmission.dx(right)*half,-.5-com.vandorlabs.propulsion.PropulsionEmission.dy(up)*half,-.5-com.vandorlabs.propulsion.PropulsionEmission.dz(up)*half);for(int x=0;x<scene.size;x++)for(int y=0;y<scene.size;y++){pose.pushPose();pose.translate(com.vandorlabs.propulsion.PropulsionEmission.dx(right)*x+com.vandorlabs.propulsion.PropulsionEmission.dx(up)*y,com.vandorlabs.propulsion.PropulsionEmission.dy(right)*x+com.vandorlabs.propulsion.PropulsionEmission.dy(up)*y,com.vandorlabs.propulsion.PropulsionEmission.dz(right)*x+com.vandorlabs.propulsion.PropulsionEmission.dz(up)*y);mc.getBlockRenderer().getModelRenderer().renderModel(pose.last(),buffers.getBuffer(layer),null,model,1,1,1,0xf000f0,OverlayTexture.NO_OVERLAY,scene.data[x*scene.size+y],layer);pose.popPose();}}finally{pose.popPose();}buffers.endBatch();gui.flush();gui.disableScissor();}if(frames==6)builds=bake.meshBuilds();else if(frames>6)need(bake.meshBuilds()==builds,"stable scenes reuse prepared chunk meshes");capture=++frames>=10;}
 private static void measure(){var visual=scenes[4].visual[0];var data=scenes[4].data[0];var random=RandomSource.create(0);var layer=NativePanelPlaybackRenderer.frameRenderType(true);for(int n=0;n<20000;n++)bake.quads(visual,null,null,random,data,layer);var meter=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();meter.setThreadAllocatedMemoryEnabled(true);long thread=Thread.currentThread().threadId(),before=meter.getThreadAllocatedBytes(thread),built=bake.meshBuilds();int vertices=0;for(int n=0;n<4096;n++)vertices+=bake.quads(visual,null,null,random,data,layer).size()*4;long allocated=meter.getThreadAllocatedBytes(thread)-before;need(allocated==0&&bake.meshBuilds()==built,"warm getQuads allocation="+allocated);need(vertices>0&&bake.retainedBytes()<=8*1024*1024,"bounded authored cache");System.out.println("[vandorlabs][propulsion-render] cost getQuads4096 vertices="+vertices+" allocated="+allocated+" newMeshes=0 retainedBytes="+bake.retainedBytes());}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event)throws Exception{if(done||(!capture&&frames!=5))return;var mc=Minecraft.getInstance();try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){double scale=mc.getWindow().getGuiScale();int w=(int)(150*scale),h=(int)(106*scale);if(frames==5){baseline=new int[12][w*h];for(int i=0;i<12;i++){int x0=(int)((10+(i%4)*155)*scale),y0=(int)((8+(i/4)*112)*scale);for(int y=0;y<h;y++)for(int x=0;x<w;x++)baseline[i][y*w+x]=image.getPixelRGBA(x0+x,y0+y);}measure();return;}done=true;var proof=mc.gameDirectory.toPath().resolve("screenshots/propulsion-native-"+generation+".png");java.nio.file.Files.createDirectories(proof.getParent());image.writeToFile(proof);int total=0;for(int i=0;i<12;i++){int x0=(int)((10+(i%4)*155)*scale),y0=(int)((8+(i/4)*112)*scale),ink=0,changed=0,blue=0,red=0;for(int y=0;y<h;y++)for(int x=0;x<w;x++){int pixel=image.getPixelRGBA(x0+x,y0+y);if((pixel&0xffffff)!=0x302820)ink++;if(pixel!=baseline[i][y*w+x])changed++;int r=pixel&255,b=(pixel>>>16)&255;if(b>r*1.4&&b>80)blue++;if(r>b*1.4&&r>80)red++;}need(ink>80,"visible authored scene="+i+" ink="+ink);if(i==1||i==3||i==4||i==11)need(changed>80,"meaningful mode/pose/material/join negative scene="+i+" changed="+changed);if(i==3)need(blue>50,"asymmetric blue emitter stays blue pixels="+blue);if(i==5)need(red>50,"asymmetric red emitter stays red pixels="+red);total+=changed;}var path=mc.gameDirectory.toPath().resolve("screenshots/propulsion-native-"+generation+".png");java.nio.file.Files.createDirectories(path.getParent());image.writeToFile(path);System.out.println("[vandorlabs][propulsion-render] generation="+generation+" negativePixels="+total);}if(generation++==0){bake=null;frames=0;capture=false;done=false;mc.reloadResourcePacks();return;}System.out.println("[vandorlabs][propulsion-render] title PASS scenes=12 sevenFamilies/6facingPoses/square+hex+wedge/3x3joined/OffOnStream/analog/sourceUV/material/asymmetricRGB/cache/reload; inactive development/software only");mc.stop();}
}
